def page(records, cursor=None, limit=10):
    if limit < 1:
        raise ValueError('limit')
    if cursor is not None:
        if not (isinstance(cursor, (list, tuple)) and len(cursor) == 2
                and isinstance(cursor[0], str) and isinstance(cursor[1], str)):
            raise ValueError('cursor')

    def key(rec):
        return (rec['timestamp'], rec['id'])

    ordered = sorted(records, key=key)
    if cursor is not None:
        cut = (cursor[0], cursor[1])
        ordered = [rec for rec in ordered if key(rec) > cut]
    items = ordered[:limit]
    last = items[-1]
    next_cursor = [last['timestamp'], last['id']] if len(ordered) > limit else None
    return {'items': items, 'next_cursor': next_cursor}
